A typical C program is built around a few well‑defined sections that give the compiler all the information it needs before the program actually runs.  
The most widely‑taught “skeletal” layout looks like this  

```
/* 1. Header files, macro definitions, type definitions … */
#include <stdio.h>
#include <stdlib.h>
#define MAX 100

/* 2. Function prototypes (declarations) */
int  compute_sum(int a, int b);
void display_result(int result);

/* 3. Global objects (constants or variables that have file scope) */
const int  LIMIT = 50;
int        global_counter = 0;

/* 4. The entry point – main() */
int main(void)
{
    /* 4a. Local variable definitions */
    int x = 10, y = 20, sum;

    /* 4b. Control structures – if, while, for, switch … */
    if (x < LIMIT) {
        sum = compute_sum(x, y);
        display_result(sum);
    }

    return 0;                     /* signal successful termination */
}

/* 5. User‑defined functions (sometimes called subroutines) */
int compute_sum(int a, int b)
{
    return a + b;
}

void display_result(int result)
{
    printf("Result = %d\n", result);
}
```

